 private nearCamp(){return !this.nearTree()&&this.wild.region===4&&Phaser.Math.Distance.Between(this.player.x,this.player.y,this.camp.stockSprite.x,this.camp.stockSprite.y)<53;}
 private resourceDistance(t:Tree){const y=t.kind==='food'?t.y-t.sprite.displayHeight*.4:t.y;return Phaser.Math.Distance.Between(t.x,y,this.player.x,this.player.y);}
