 private updateNpc(now:number){if(this.wild.region===RIVERHAVEN)return;if(now<this.npcCheck&&this.npcRegion===this.wild.region)return;this.npcCheck=now+1000;const r=this.wild.region;const n=currentNpc(this.npcState,r,now);if(n?.id===this.npcId&&r===this.npcRegion)return;this.npcSprite?.destroy();this.npcSprite=undefined;this.npcId=n?.id??0;this.npcRegion=r;if(!n)return;const x=r===4?145:145,y=r===4?255:235;this.npcSprite=this.add.sprite(x,y,'npc',n.frame).setOrigin(.5,1).setDisplaySize(36,36).setDepth(y);this.save();}
 private nearNpc(){if(this.wild.region===RIVERHAVEN){const n=this.villageNpcs.filter(n=>Phaser.Math.Distance.Between(this.player.x,this.player.y,n.sprite.x,n.sprite.y)<30).sort((a,b)=>Phaser.Math.Distance.Between(this.player.x,this.player.y,a.sprite.x,a.sprite.y)-Phaser.Math.Distance.Between(this.player.x,this.player.y,b.sprite.x,b.sprite.y))[0];if(n)this.npcId=n.id;return !!n;}return this.npcSprite&&this.npcRegion===this.wild.region&&Phaser.Math.Distance.Between(this.player.x,this.player.y,this.npcSprite.x,this.npcSprite.y)<35;}
