 private die(cause:string){if(cause==='rabbit boss')this.wild.rabbitDeaths=(this.wild.rabbitDeaths??0)+1;if(this.campRestLeft)this.finishCampRest(false);const lines:Record<string,string>={goblin:'A goblin has defeated you. Somewhere, a very small creature is telling a very large story.', 'Goblin King':'Congratulations on your audience with royalty. It was brief, and mostly involved the floor.',bandit:'The bandit wanted your valuables. Apparently your dignity was included.', 'rabbit boss':'You lost a fight with a rabbit. The forest will be discussing this for generations.',thirst:'Surrounded by nature, defeated by a missing beverage. Outstanding.',starvation:'Gruk forgot lunch. Lunch did not forget Gruk.'};const lost=cause==='rabbit boss'?['Nothing but your dignity']:resources.map(r=>{const before=this.player.inventory[r];this.player.inventory[r]=Math.floor(before*.8);return `${before-this.player.inventory[r]} ${r}`;});this.enterRegion(4);this.player.setPosition(180,230);this.wild.combatUntil=0;this.wild.drinkReadyAt=0;this.wild.health=this.wild.hunger=this.wild.thirst=100;this.wild.deaths=(this.wild.deaths??0)+1;this.save();this.wild.stamina=100;this.wild.pendingDeath={cause,body:lines[cause]??'An impressive failure of basic survival.',lost:lost.join(' • ')};this.save();this.showDeath();}
