 private showDeath(){const death=this.wild.pendingDeath;if(!death||this.deathOverlay)return;this.closeMenu();const overlay=document.createElement('section');this.deathOverlay=overlay;Object.assign(overlay.style,{position:'fixed',inset:'0',zIndex:'2147483647',background:'#171510ee',display:'grid',placeItems:'center',padding:'20px',color:'#f5dfb6'});overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');const box=document.createElement('div');Object.assign(box.style,{maxWidth:'480px',maxHeight:'90vh',overflow:'auto',textAlign:'center'});const heading=document.createElement('h2');heading.textContent='Well, that was embarrassing.';const body=document.createElement('p');body.textContent=`Slain by: ${death.cause}. ${death.body} Lost: ${death.lost}.`;const timer=document.createElement('p');const respawn=document.createElement('button'),giveup=document.createElement('button');respawn.textContent='Respawn';giveup.textContent='Give up forever';respawn.disabled=giveup.disabled=true;box.append(heading,body,timer,respawn,giveup);overlay.append(box);document.body.append(overlay);let remaining=10;timer.textContent='Choose your fate in 10 seconds.';this.deathTimer=window.setInterval(()=>{remaining--;timer.textContent=remaining>0?`Choose your fate in ${remaining} seconds.`:'Choose your fate.';if(remaining<=0){window.clearInterval(this.deathTimer);respawn.disabled=giveup.disabled=false;}},1000);respawn.onclick=()=>{delete this.wild.pendingDeath;overlay.remove();this.deathOverlay=undefined;this.input.keyboard?.resetKeys();this.save();};giveup.onclick=()=>{if(!window.confirm('Permanently erase this Blackroot save? This cannot be undone.'))return;if(!SaveSystem.reset()){timer.textContent='Could not erase save. Try again.';return;}this.resetting=true;location.reload();};}

