 private farmSites(){const w=this.wild,sites=w.farmSites??=[];const blocked=this.farmBlocked();const count=Math.ceil((w.farmPlots?.length??0)/4);for(let i=0;i<count;i++){let site=sites[i];if(!site||site.x<20||site.y<110||site.x+site.width>340||site.y+site.height>480||site.width!==80||site.height!==30||blocked.some(b=>overlaps(site,b)))site=findFarmSite(blocked)!;if(site){sites[i]=site;blocked.push(site);}else delete sites[i];}return {sites,blocked};}
