 private lumber(b:'mill'|'yard'){if(this.menu||this.inCombat()||this.wild.region!==4||!this.camp.built.includes(b))return;const w=this.wild,l=b==='mill'?w.millLevel??1:w.yardLevel??1;const ui=this.responsive.openDialog(b==='mill'?'Lumber Mill':'Lumber Yard',()=>this.closeMenu());this.menu=ui.token;const refresh=()=>{this.save();this.closeMenu();this.lumber(b);};const cap=this.woodCapacity();ui.note(`Level ${l}/10 • Shared lumber workforce ${this.camp.workers.wood}/${cap}`);ui.note(`Lifetime wood since tracking began: ${w.woodProduced??0} • Combined lumber production ${this.woodRate()}/hour`);ui.note(`Next hourly cycle in ${Math.ceil((3600000-this.production)/60000)} min • Requires stored food`);const cost={wood:250*l,stone:100*l};ui.row('Upgrade',l<10?costText(cost)+' • +10% efficiency, +1 capacity':'Maximum level','Upgrade',()=>{if(l<10&&spend(this.camp.storage,cost)){if(b==='mill')w.millLevel=l+1;else w.yardLevel=l+1;this.xp('Construction',100);}refresh();},l<10&&this.camp.storage.wood>=cost.wood&&this.camp.storage.stone>=cost.stone);ui.row('Hire lumberjack','50 food • housing required','Hire',()=>{if(this.story.data.urga&&this.camp.workers.wood<this.woodCapacity()&&this.story.population(this.camp.workers)<this.story.capacity&&spend(this.camp.storage,{food:50}))this.camp.workers.wood++;refresh();},this.story.data.urga&&this.camp.workers.wood<cap&&this.story.population(this.camp.workers)<this.story.capacity&&this.camp.storage.food>=50);ui.row('All workers','Manage village workforce','Open',()=>{this.closeMenu();this.page=2;this.openMenu();});}
